SELECT module_srl, mid, browser_title
FROM xe_modules
WHERE mid = #{mid}

SELECT d.document_srl, d.module_srl, m.mid, d.title, d.content, d.status, d.regdate, d.last_update FROM xe_documents d INNER JOIN xe_modules m ON m.module_srl = d.module_srl WHERE m.mid IN
#{managedMid}
AND d.document_srl IN
#{documentSrl}
ORDER BY d.document_srl DESC

SELECT d.document_srl, d.module_srl, m.mid, d.title, d.content, d.status, d.regdate, d.last_update FROM xe_documents d INNER JOIN xe_modules m ON m.module_srl = d.module_srl WHERE m.mid IN
#{managedMid}
AND m.mid = #{mid}
AND ( LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(d.title, ' ', ''), '-', ''), '_', ''), '/', ''), '.', ''), '(', ''), ')', '')) LIKE CONCAT('%', #{normalizedKeyword}, '%')
OR
LOWER(d.title) LIKE CONCAT('%', #{keywordToken}, '%')
)
ORDER BY d.document_srl DESC LIMIT #{limit} OFFSET #{offset}

SELECT d.document_srl, d.module_srl, m.mid, d.title, d.content, d.status, d.regdate, d.last_update FROM xe_documents d INNER JOIN xe_modules m ON m.module_srl = d.module_srl WHERE m.mid IN
#{managedMid}
AND d.document_srl < #{afterDocumentSrl}
AND m.mid = #{mid}
AND ( LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(d.title, ' ', ''), '-', ''), '_', ''), '/', ''), '.', ''), '(', ''), ')', '')) LIKE CONCAT('%', #{normalizedKeyword}, '%')
OR
LOWER(d.title) LIKE CONCAT('%', #{keywordToken}, '%')
)
ORDER BY d.document_srl DESC LIMIT #{limit}

SELECT COUNT(*) FROM xe_documents d INNER JOIN xe_modules m ON m.module_srl = d.module_srl WHERE m.mid IN
#{managedMid}
AND m.mid = #{mid}
AND ( LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(d.title, ' ', ''), '-', ''), '_', ''), '/', ''), '.', ''), '(', ''), ')', '')) LIKE CONCAT('%', #{normalizedKeyword}, '%')
OR
LOWER(d.title) LIKE CONCAT('%', #{keywordToken}, '%')
)

