)

UPDATE xe_documents
SET
    status = #{status},
    last_update = #{lastUpdate}
WHERE document_srl = #{documentSrl}
  AND module_srl IN (
    SELECT module_srl
    FROM xe_modules
    WHERE mid IN

        #{managedMid}

  )
